for l, t in T.items():
    p = f'notice_{l}.json'
    d = json.load(open(p))
    d['ver'] = d['ver'].replace('0.3.0', '0.3.1')
    s = d['s']
    s[1]['p'][0] = t['s1p0']; s[1]['leg'] = t['leg1']
    assert len(s[7]['p']) == 3
    s[7]['p'][2] = t['s7p2']; s[7]['p'].append(t['s7p3'])
    s[7]['cap2'] = t['cap2']; s[7]['leg2'] = t['leg2']
    s[8]['p'][1] = t['s8p1']
    s[12]['p'][1] = t['s12p1']
    assert len(s[14]['p']) == 3
    s[14]['p'][0] = t['s14p0']; s[14]['p'][2] = t['s14p2']; s[14]['p'].append(t['s14p3'])
    assert len(t['leg1']) == 11 and len(t['leg2']) == 5
    json.dump(d, open(p, 'w'), ensure_ascii=False, indent=1)
print('notice 0.3.1 : 10 langues')
